using System;using System.Data;using System.Text;public partial class AddBet:System.Web.UI.Page{public string GamesScript="",DateOptions="",st="";protected void Page_Load(object sender,EventArgs e){if(Session["user"]==null){Response.Redirect("Login.aspx");return;}LoadData();if(Page.IsPostBack)SaveBet();}private void LoadData(){string sql="SELECT Games.GameId,Games.GameDate,Games.ClubAId,Games.ClubBId,A.ClubName ClubA,B.ClubName ClubB FROM Games INNER JOIN Clubs A ON Games.ClubAId=A.ClubId INNER JOIN Clubs B ON Games.ClubBId=B.ClubId WHERE Games.GameResult=N'-1' AND Games.GameDate>GETDATE() ORDER BY Games.GameDate";DataTable dt=MyAdoHelper.ExecuteDataTable(sql);StringBuilder js=new StringBuilder("var games=[");StringBuilder dates=new StringBuilder();string last="";for(int i=0;i<dt.Rows.Count;i++){string d=Convert.ToDateTime(dt.Rows[i]["GameDate"]).ToString("dd/MM/yyyy");if(d!=last){dates.Append("<option value='"+d+"'>"+d+"</option>");last=d;}if(i>0)js.Append(",");js.Append("{id:'"+dt.Rows[i]["GameId"]+"',date:'"+d+"',aid:'"+dt.Rows[i]["ClubAId"]+"',bid:'"+dt.Rows[i]["ClubBId"]+"',a:'"+dt.Rows[i]["ClubA"]+"',b:'"+dt.Rows[i]["ClubB"]+"'}");}js.Append("];");GamesScript=js.ToString();DateOptions=dates.ToString();}private void SaveBet(){int gid,cid,coins;if(!int.TryParse(Request.Form["gameId"],out gid)||!int.TryParse(Request.Form["betClubId"],out cid)||!int.TryParse(Request.Form["betCoins"],out coins)||coins<=0){st="נתוני ההימור אינם תקינים";return;}DataTable g=MyAdoHelper.ExecuteDataTable("SELECT * FROM Games WHERE GameId="+gid);if(g.Rows.Count==0||Convert.ToDateTime(g.Rows[0]["GameDate"])<=DateTime.Now||g.Rows[0]["GameResult"].ToString()!="-1"){st="לא ניתן להמר על משחק זה";return;}if(cid!=Convert.ToInt32(g.Rows[0]["ClubAId"])&&cid!=Convert.ToInt32(g.Rows[0]["ClubBId"])){st="הקבוצה אינה משתתפת במשחק";return;}int uid=Convert.ToInt32(Session["userId"]);DataTable u=MyAdoHelper.ExecuteDataTable("SELECT Coins FROM Users WHERE UserId="+uid);int have=Convert.ToInt32(u.Rows[0]["Coins"]);if(coins>have){st="אין מספיק מטבעות";return;}MyAdoHelper.DoQuery("INSERT INTO Bets(UserId,GameId,BetDate,BetCoins,BetClubId,BetResult) VALUES("+uid+","+gid+",GETDATE(),"+coins+","+cid+",-1)");MyAdoHelper.DoQuery("UPDATE Users SET Coins=Coins-"+coins+" WHERE UserId="+uid);Session["coins"]=(have-coins).ToString();st="ההימור נשמר בהצלחה";}}